import "./PlayerInfo.css";
import { useState } from "react";

const PlayerInfo = ({ PName, symbol }) => {
  const [editing, setEditing] = useState(false);

  const handleClicking = () => {
    setEditing((prev) => !prev); // toggles between true/false
  };

  // const changeInput = () => {
  //   if (editing) {
  //     console.log(editing);
  //     return <input className="player-name" />;
  //   } else if (editing === false) {
  //     return <span className="player-name">{PName}</span>;
  //   }
  // };

  let changeInput = <span className="player-name">{PName}</span>;

  if (editing) {
    changeInput = <input className="player-name" />;
  } else {
    changeInput = (
      <span className="player-name">{editing ? changeInput.value : PName}</span>
    );
  }

  return (
    <div className="player">
      {changeInput}
      <p className="player-symbol">{symbol}</p>
      <button className="edit-btn" onClick={handleClicking}>
        {editing ? "Save" : "Edit"}
      </button>
    </div>
  );
};

export default PlayerInfo;
